        } catch (e) {}
        return { result: false };
    }

    // Branch exists — create a new PR/MR so review can proceed
    console.log('Branch exists but no PR — creating PR for review...');
    try {
        return { found: createReviewPrForBranch(scm, ticketKey, branchName, config) };
