+                { match: 'git ls-files --stage -- "src/app.js"', output: '100644 abc123 1\tsrc/app.js' },
+                { match: 'git diff mb-sha HEAD -- "src/app.js"', output: '' },
+                { match: 'git diff --name-only --diff-filter=U', output: '' },
+                { match: 'git commit', output: 'ok' }
+            ])
+        });
+
